parameters.jsCode:
const input = $input.first().json;
let s;
try {
  const raw = input.choices[0].message.content;
  s = JSON.parse(raw);
} catch (e) {
  s = {};
}
// Guard: malformed/missing AI fields fall back to 0 instead of NaN -> NULL
const skills = Number(s.skills_score) || 0;
const experience = Number(s.experience_score) || 0;
const projects = Number(s.projects_score) || 0;
const weighted = Math.round((skills*0.4) + (experience*0.35) + (projects*0.25));
const recommendation = weighted >= 80 ? 'Shortlist Recommended' : weighted >= 60 ? 'Review Required' : 'Not Recommended';
const application = $('Insert Application into DB').first().json;
return [{ json: {
  application_id: application.id,
  weighted_score: weighted,
  ai_summary: `Skills: ${skills} | Experience: ${experience} | Projects: ${projects} | Recommendation: ${recommendation}`,
  matched_skills: s.matched_skills || [],
  missing_skills: s.missing_skills || []
} }];

parameters.query:
UPDATE applications SET score = $1, ai_summary = $2, matched_skills = $3, missing_skills = $4
WHERE id = $5
RETURNING *;

INSERT INTO applications (job_id, candidate_id, stage, matched_skills)
VALUES ($1, $2, 'applied', $3)
RETURNING *;

